import sys

def find_arithmetic_progressions(n, a):
    if n <= 2:
        return [a], []

    def is_ap(seq):
        if len(seq) <= 2:
            return True
        d = seq[1] - seq[0]
        return all(seq[i] - seq[i - 1] == d for i in range(2, len(seq)))

    for i in range(1, n):
        for j in range(i + 1, n):
            ap1 = a[:i]
            ap2 = a[i:j]
            ap3 = a[j:]
            if is_ap(ap1 + ap2) and is_ap(ap2 + ap3):
                if is_ap(ap1) and is_ap(ap3):
                    return ap1 + ap2, ap3
                if is_ap(ap1) and is_ap(ap2 + ap3):
                    return ap1, ap2 + ap3
            if is_ap(ap1 + ap3) and is_ap(ap2):
                if is_ap(ap1) and is_ap(ap3):
                    if ap1[-1] < ap2[0]:
                        return ap1 + ap3, ap2
                    else:
                        return ap2, ap1 + ap3
                if is_ap(ap1 + ap3) and is_ap(ap2):
                    return ap1 + ap3, ap2
            if is_ap(ap1) and is_ap(ap2) and is_ap(ap3):
                return ap1, ap2 + ap3

    return None, None

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))

    ap1, ap2 = find_arithmetic_progressions(n, a)

    if ap1 is None or ap2 is None:
        print("No solution")
    else:
        print(" ".join(map(str, ap1)))
        print(" ".join(map(str, ap2)))

if __name__ == "__main__":
    main()
